// UpdateMany updates multiple PlaidItem records matching the filter
func (r *PlaidItemRepository) UpdateMany(ctx context.Context, filter *PlaidItemFilter, update *PlaidItemUpdate) (int, error) {
	// Each row's envelope is bound to its own key, so one statement cannot
	// set an encrypted field of many rows (D85).
	if field := plaidItemSetsEncrypted(update); field != "" {
		return 0, fmt.Errorf("update PlaidItem: %w", &EncryptedWriteError{Table: "PlaidItem", Field: field, Write: "UpdateMany"})
	}
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.ItemId != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`item_id = $%d`, paramNum))
		values = append(values, *update.ItemId)
	}
	if update.Institution != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`institution = $%d`, paramNum))
		values = append(values, *update.Institution)
	}
	if update.AccessToken != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`access_token = $%d`, paramNum))
		values = append(values, *update.AccessToken)
	}
	if update.WebhookSecret != nil && update.WebhookSecretSetNull {
		return 0, fmt.Errorf("webhook_secret cannot be updated with both value and null assignment")
	}
	if update.WebhookSecretSetNull {
		setClauses = append(setClauses, `webhook_secret = NULL`)
	} else if update.WebhookSecret != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`webhook_secret = $%d`, paramNum))
		values = append(values, *update.WebhookSecret)
	}

	// Set updated_at
	paramNum++
	setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
	values = append(values, time.Now())

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)
	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}

	query := fmt.Sprintf(
		`UPDATE plaid_item SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne soft deletes a single PlaidItem record by ID
func (r *PlaidItemRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE plaid_item SET deleted_at = $1 WHERE id = $2 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteMany soft deletes multiple PlaidItem records matching the filter
func (r *PlaidItemRepository) DeleteMany(ctx context.Context, filter *PlaidItemFilter) (int, error) {
	if !HasUserID(ctx) {
		return 0, ErrNoUserInContext
	}

	// Build WHERE clause
	values := []interface{}{time.Now()}
	whereClause := filter.buildWhereClause(&values, 1)

	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}
	query := fmt.Sprintf(`UPDATE plaid_item SET deleted_at = $1%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// HardDeleteOne permanently deletes a single PlaidItem record by ID
func (r *PlaidItemRepository) HardDeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM plaid_item WHERE id = $1`
	queryArgs := []interface{}{id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}
